type NodeIter struct{ stack []*Node; cur *Node }

func (it *NodeIter) Next() bool {
    if len(it.stack) == 0 { return false }
    n := it.stack[len(it.stack)-1]
    it.stack = append(it.stack[:len(it.stack)-1], n.children...)
    it.cur = n
    return true
}
func (it *NodeIter) Node() *Node { return it.cur }   // any Go version
